from pathlib import Path
import json,re,hashlib
C=Path(__file__).resolve().parent.parent;P=C/'proof';NS=json.loads((P/'originals.json').read_text())['namespace'];sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest();rows=[]
def add(statusfile,stem,source,typed):
 sf=P/statusfile;d=json.loads(sf.read_text());assert d['passed']and d.get('vc_correct_passed');run=Path(d['run_directory']);goal=run/'coq'/(stem+'_goal.v');cpp=run/(stem+'.c');assert goal.exists()and cpp.exists(),(stem,run);g=goal.read_text();fields=re.findall(r'^Axiom proof_of_(\w+)',g,re.M);assert fields and len(fields)==len(set(fields));ss=C/source;assert ss.exists();rows.append({'stem':stem,'namespace':NS,'source':source,'source_sha256':sha(ss),'goal_path':str(goal),'goal_sha256':sha(goal),'cpp_path':str(cpp),'cpp_sha256':sha(cpp),'fields':fields,'actual_c_vcs':len(fields),'typed_instance':NS+'.'+typed,'component_status':'proof/'+statusfile,'component_status_sha256':sha(sf),'component_passed':True,'strategies':[],'source_kind':'actual C body, native public spec for wrapper'if stem=='wrapper_unit'else'actual case-local C helper body','identity_note':'Historical checked component. Full gate must regenerate current CPP/goal and fresh compile necessary source DAG; this inventory adds no proof credit.'})
