for status,stem,source in [('read-byte-status.json','read_byte','shim/read_byte.c'),('load-scalar-status.json','load_scalar','shim/load_scalar.c'),('output-scalar-status.json','output_scalar','shim/output_scalar.c'),('output-active-status.json','output_active','shim/output_active.c'),('vl-status.json','vl_control','shim/vl_control.c'),('compare-status.json','public_compare','shim/public_compare.c'),('wrapper-status.json','wrapper_unit','spec.c')]:
 d=json.loads((P/status).read_text());assert d['typed_instance'].startswith(NS+'.');add(status,stem,source,d['typed_instance'][len(NS)+1:])
