 gf=P/(side+'-generation-status.json');d=json.loads(gf.read_text());assert d['generation_passed'];run=Path(d['run_directory']);stem=side+'_unit';goal=run/(stem+'_goal.v');cpp=run/(stem+'.c');assert sha(goal)==d['goal_sha256']and sha(cpp)==d['cpp_sha256'];fields=re.findall(r'^Axiom proof_of_(\w+)',goal.read_text(),re.M);assert len(fields)==n;src='impl/test'+('NEON'if side=='neon'else'RVV')+'.c';rows.append({'stem':stem,'namespace':NS,'source':src,'source_sha256':sha(C/src),'goal_path':str(goal),'goal_sha256':sha(goal),'cpp_path':str(cpp),'cpp_sha256':sha(cpp),'fields':fields,'actual_c_vcs':n,'typed_instance':NS+'.'+typed,'component_status':'proof/'+side+'-proof-status.json','component_status_exists':(P/(side+'-proof-status.json')).exists(),'generation_status':'proof/'+side+'-generation-status.json','generation_status_sha256':sha(gf),'annotation':'proof/c/'+side+'.annotations.json','strategies':[],'source_kind':'repaired actual kernel plus deterministic annotation injection; source and frontend CPP token identity in generation receipt','annotation_sha256':sha(P/'c'/(side+'.annotations.json')),'generation_matches_current_annotation':d['annotation_sha256']==sha(P/'c'/(side+'.annotations.json')),'component_passed':False,'identity_note':'All individual fields checked separately; full typed interface still being replayed. No whole-case credit.'})
